Bash(node -e "
const ts = require\('typescript'\);
const fs = require\('fs'\);
const files = ['src/monitor.ts', 'src/agent/handler.ts'];
for \(const f of files\) {
    const content = fs.readFileSync\(f, 'utf8'\);
    const result = ts.transpileModule\(content, { compilerOptions: { module: ts.ModuleKind.ES2022, target: ts.ScriptTarget.ES2022 }}\);
    if \(result.diagnostics && result.diagnostics.length > 0\) {
        console.log\('Errors in', f\);
        result.diagnostics.forEach\(d => console.log\(d.messageText\)\);
    } else {
        console.log\(f, ': OK'\);
    }
}
")
